html:div.html:script:
(async function () {
  const source = "https://cdn.jsdelivr.net/gh/hiwa1do/scramjet-browser@main/index.html";
  const status = document.getElementById("status");
  const frame = document.getElementById("app");

  try {
    const response = await fetch(source, { cache: "no-store" });
    if (!response.ok) throw new Error("HTTP " + response.status);

    let html = await response.text();

    // Keep relative assets pointed at the original jsDelivr directory.
    const base = '<base href="https://cdn.jsdelivr.net/gh/hiwa1do/scramjet-browser@main/">';
    if (/<head[^>]*>/i.test(html)) {
      html = html.replace(/<head([^>]*)>/i, '<head$1>' + base);
    } else {
      html = base + html;
    }

    frame.srcdoc = html;
    frame.style.display = "block";
    status.style.display = "none";
  } catch (error) {
    status.textContent = "Could not load the page: " + error.message
      + " — open this SVG from a local web server (localhost), not as an image.";
  }
})();
